main() {
    extrn printf;
    auto i;

    i = 0;
    while (++i <= 15) {
        if (i % 15 == 0)
            printf("FizzBuzz*n");
        else if (i % 3 == 0)
            printf("Fizz*n");
        else if (i % 5 == 0)
            printf("Buzz*n");
        else
            printf("%d*n", i);
    }
}

higher-order.code:
/* No lambdas, but a function is just a word: pass it along. */
even(x) return (x % 2 == 0);
square(x) return (x * x);

filtermap(v, n, p, f, out) {
    auto i, k;

    i = k = 0;
    while (i < n) {
        if (p(v[i]))
            out[k++] = f(v[i]);
        i++;
    }
    return (k);
}

main() {
    extrn printf, even, square;
    auto v[10], w[10], i, k;

    i = 0;
    while (i < 10) {
        v[i] = i + 1;
        i++;
    }
    k = filtermap(v, 10, even, square, w);
    printf("%d", w[0]);
    i = 1;
    while (i < k)
        printf(" %d", w[i++]);
    printf("*n");
}

shapes.code:
/* No types or structs: a shape is a vector {area function, name, a, b}. */
rectarea(s) return (s[2] * s[3]);
triarea(s) return (s[2] * s[3] / 2);

show(s) {
    extrn printf;
    printf("%s: %d*n", s[1], s[0](s));
}

main() {
    extrn rectarea, triarea;
    auto r[4], t[4];

    r[0] = rectarea; r[1] = "Rectangle"; r[2] = 3;  r[3] = 4;
    t[0] = triarea;  t[1] = "Triangle";  t[2] = 10; t[3] = 3;
    show(r);
    show(t);
}

signature.code:
/* B has one type, the machine word: a number, a pointer,
   a function or a few packed characters. */
main() {
    extrn putchar, printf, a, b, c, v, twice;
    auto p, f;

    putchar(a); putchar(b); putchar(c); putchar('!*n');
    p = &v[1];                             /* a pointer is a word */
    printf("%d %d %d*n", *p, p[1], 1[p]);  /* E1[E2] means *(E1+E2) */
    f = twice;                             /* so is a function */
    p = 20;
    p =+ f(11);                            /* B's =+ became C's += */
    printf("%d*n", p);
}

twice(x) return (x + x);

